module interesting_problemset (\n    input [2:0] k,\n    input [15:0] presence,\n    output reg ans\n);\n\n    always @(*) begin\n        if (presence[0]) begin\n            ans = 1'b1;\n        end else if (k == 3'd1) begin\n            ans = 1'b0;\n        end else begin\n            ans = 1'b0;\n            for (integer i = 0; i < 16; i = i + 1) begin\n                for (integer j = i + 1; j < 16; j = j + 1) begin\n                    if (presence[i] && presence[j] && ( (i & j) == 0 )) begin\n                        ans = 1'b1;\n                    end\n                end\n            end\n        end\n    end\n\nendmodule